"ui.R" :

library(shinydashboard)

shinyUI <- dashboardPage(

  dashboardHeader(title="App Test"),

  dashboardSidebar(

    sidebarMenu(

      menuItem("Menu 1", tabName = "menu1", icon = icon("question-circle")),
