                             tabPanel("Tab 1", p("Tab 1 : right")),
                             tabPanel("Tab 2", p("Tab 2 : right")),
                             tabPanel("Tab 3", p("Tab 3 : right")),
                             width = NULL
                      )

                  )

              )

      ),

      tabItem(tabName = "menu2",

